// src/config.js: the app scheme must be the same everywhere, or sign-in cannot come back to the
// app: app.json "scheme", the checked-in Android intent filter (generated by expo prebuild), and
// the backend's MOBILE_APP_SCHEME default and .env.example.
const fs = require('fs');
const path = require('path');

const { APP_SCHEME, AUTH_REDIRECT_URI, API_URL } = require('../../mobile/src/config');

const MOBILE_DIR = path.join(__dirname, '../../mobile');
const BACKEND_DIR = path.join(__dirname, '../../backend');

function read(file) {
  return fs.readFileSync(file, 'utf8');
}

describe('app scheme', () => {
  it('is the app\'s applicationId / bundle identifier', () => {
    const { expo } = JSON.parse(read(path.join(MOBILE_DIR, 'app.json')));
    expect(APP_SCHEME).toBe('com.matmss.mobile');
    expect(expo.scheme).toBe(APP_SCHEME);
    expect(expo.android.package).toBe(APP_SCHEME);
    expect(expo.ios.bundleIdentifier).toBe(APP_SCHEME);
  });

  it('is handled by the Android main activity', () => {
    const manifest = read(path.join(MOBILE_DIR, 'android/app/src/main/AndroidManifest.xml'));
    const filters = manifest.match(/<intent-filter>[\s\S]*?<\/intent-filter>/g) || [];
    const viewFilter = filters.find((filter) => filter.includes(`android:scheme="${APP_SCHEME}"`));
    expect(viewFilter).toBeDefined();
    expect(viewFilter).toContain('android.intent.action.VIEW');
    expect(viewFilter).toContain('android.intent.category.BROWSABLE');
  });

  it('excludes the secure store from Android Auto Backup', () => {
    const manifest = read(path.join(MOBILE_DIR, 'android/app/src/main/AndroidManifest.xml'));
    expect(manifest).toContain('android:fullBackupContent="@xml/secure_store_backup_rules"');
    expect(manifest).toContain('android:dataExtractionRules="@xml/secure_store_data_extraction_rules"');
  });

  it('is the backend\'s MOBILE_APP_SCHEME default and .env.example value', () => {
    const authConfig = read(path.join(BACKEND_DIR, 'src/config/auth.js'));
    expect(authConfig).toMatch(new RegExp(`DEFAULT_MOBILE_APP_SCHEME = '${APP_SCHEME.replace(/\./g, '\\.')}'`));
    expect(read(path.join(BACKEND_DIR, '.env.example'))).toMatch(new RegExp(`^MOBILE_APP_SCHEME=${APP_SCHEME.replace(/\./g, '\\.')}$`, 'm'));
  });

  it('passes the backend\'s scheme shape allow-list', () => {
    expect(APP_SCHEME).toMatch(/^[a-z][a-z0-9]*(?:[.-][a-z0-9]+)*$/);
  });

  it('builds the sign-in redirect on it', () => {
    expect(AUTH_REDIRECT_URI).toBe('com.matmss.mobile://auth/callback');
  });
});

describe('API URL', () => {
  it('falls back to the local backend', () => {
    expect(API_URL).toBe(process.env.EXPO_PUBLIC_API_URL || 'http://localhost:3333');
  });
});
